  'app.footerTagline': { 'pt-BR':'Dados públicos. Métodos visíveis. Comparações com contexto.', en:'Public data. Visible methods. Comparisons in context.', es:'Datos públicos. Métodos visibles. Comparaciones con contexto.', de:'Öffentliche Daten. Sichtbare Methoden. Vergleiche im Kontext.', fr:'Données publiques. Méthodes visibles. Comparaisons en contexte.', ru:'Открытые данные. Прозрачные методы. Сравнения в контексте.', 'zh-CN':'公开数据。透明方法。情境化比较。', ja:'公開データ。見える方法論。文脈のある比較。', ko:'공개 데이터. 투명한 방법. 맥락 속 비교.', pl:'Dane publiczne. Widoczne metody. Porównania w kontekście.' },
